        return self.eval_ctx.__dict__.copy()

    def revert_eval_context(self, old: t.Mapping[str, t.Any]) -> None:
        """Restore eval context state from a previously saved snapshot."""
        self.eval_ctx.__dict__.clear()
        self.eval_ctx.__dict__.update(old)

